// Copyright (c) HashiCorp, Inc.
// SPDX-License-Identifier: BUSL-1.1

package terraform

import (
	"log"
	"strings"

	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/configs"
	"github.com/hashicorp/terraform/internal/dag"
)

// GraphNodeAttachResourceConfig is an interface that must be implemented by nodes
// that want resource configurations attached.
type GraphNodeAttachResourceConfig interface {
	GraphNodeConfigResource

	// Sets the configuration, either to a present resource block or to
	// a "removed" block commemorating a resource that has since been
	// removed. Callers should always leave at least one of these
	// arguments set to nil.
	AttachResourceConfig(*configs.Resource, *configs.Removed)
}

// AttachResourceConfigTransformer goes through the graph and attaches
// resource configuration structures to nodes that implement
// GraphNodeAttachManagedResourceConfig or GraphNodeAttachDataResourceConfig.
//
// The attached configuration structures are directly from the configuration.
// If they're going to be modified, a copy should be made.
type AttachResourceConfigTransformer struct {
	Config *configs.Config // Config is the root node in the config tree
}

func (t *AttachResourceConfigTransformer) Transform(g *Graph) error {
	// Collect all of the removed blocks across the whole configuration tree
	// up front, because a removed block can target a resource in a descendant
	// module (for example, "from = module.child.test_object.a"), including a
	// module that has itself been removed from the configuration.
	removedBlocks := make(map[string]*configs.Removed)
	t.findRemovedBlocks(t.Config, removedBlocks)

	for _, v := range g.Vertices() {
		arn, ok := v.(GraphNodeAttachResourceConfig)
		if !ok {
			continue
		}

		addr := arn.ResourceAddr()
		vertexName := dag.VertexName(v)
		res := addr.Resource
		resType := res.Type
		resName := res.Name

		var modulePath strings.Builder
		modulePath.Grow(len(addr.Module) * 16)
		modSep := ""
		for _, step := range addr.Module {
			modulePath.WriteString(modSep)
			modulePath.WriteString("module.")
			modulePath.WriteString(step)
			modSep = "."
		}
		modulePathStr := modulePath.String()

		config := t.Config
		for _, step := range addr.Module {
			config = config.Children[step]
			if config == nil {
				break
			}
		}

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", vertexName, v)
		} else {
			mod := config.Module
			managedResources := mod.ManagedResources
			dataResources := mod.DataResources
			providerMetas := mod.ProviderMetas

			var lookupKey strings.Builder
			lookupKey.Grow(len(resType) + len(resName) + 6)
			var resourceCfg *configs.Resource
			if res.Mode == addrs.ManagedResourceMode {
				lookupKey.WriteString(resType)
				lookupKey.WriteByte('.')
				lookupKey.WriteString(resName)
				resourceCfg = managedResources[lookupKey.String()]
			} else if res.Mode == addrs.DataResourceMode {
				lookupKey.WriteString("data.")
				lookupKey.WriteString(resType)
				lookupKey.WriteByte('.')
				lookupKey.WriteString(resName)
				resourceCfg = dataResources[lookupKey.String()]
			}
			lookupKeyStr := lookupKey.String()
			log.Printf("[TRACE] AttachResourceConfigTransformer: resolving %q module %q key %q", vertexName, modulePathStr, lookupKeyStr)

			if resourceCfg != nil {
				declRange := resourceCfg.DeclRange
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", vertexName, v, declRange)
				arn.AttachResourceConfig(resourceCfg, nil)
				if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
					log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", vertexName)
					if providerMetas != nil {
						gnapmc.AttachProviderMetaConfigs(providerMetas)
					} else {
						log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", vertexName)
					}
				}
			}
		}

		if removedBlock, ok := removedBlocks[addr.String()]; ok {
			removedDecl := removedBlock.DeclRange
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", vertexName, v, removedDecl)
			arn.AttachResourceConfig(nil, removedBlock)
		}
	}

	return nil
}

// findRemovedBlocks records the removed blocks for all resources in the
// configuration, keyed by their absolute configuration address.
//
// A removed block in a parent module overrides a removed block in a child
// module when both target the same object, so we walk the configuration tree
// from the root and keep the first block we find for each address.
func (t *AttachResourceConfigTransformer) findRemovedBlocks(cfg *configs.Config, into map[string]*configs.Removed) {
	if cfg == nil || cfg.Module == nil {
		return
	}

	for _, removedBlock := range cfg.Module.Removed {
		if removedBlock.From == nil {
			continue
		}

		crAddr, ok := removedBlock.From.RelSubject.(addrs.ConfigResource)
		if !ok {
			// Not for a resource at all, so can't possibly match.
			continue
		}

		module := make(addrs.Module, 0, len(cfg.Path)+len(crAddr.Module))
		module = append(module, cfg.Path...)
		module = append(module, crAddr.Module...)
		absAddr := addrs.ConfigResource{
			Module:   module,
			Resource: crAddr.Resource,
		}

		key := absAddr.String()
		if _, exists := into[key]; exists {
			continue
		}
		into[key] = removedBlock
	}

	for _, child := range cfg.Children {
		t.findRemovedBlocks(child, into)
	}
}

state.output:
	}

	return state, keyData, diags
}

// evalApplyProvisioners determines if provisioners need to be run, and if so
// executes the provisioners for a resource and returns an updated error if
// provisioning fails.
func (n *NodeAbstractResourceInstance) evalApplyProvisioners(ctx EvalContext, state *states.ResourceInstanceObject, createNew bool, when configs.ProvisionerWhen) tfdiags.Diagnostics {
	var diags tfdiags.Diagnostics

	if state == nil {
		log.Printf("[TRACE] evalApplyProvisioners: %s has no state, so skipping provisioners", n.Addr)
		return nil
	}
	if when == configs.ProvisionerWhenCreate && !createNew {
		// If we're not creating a new resource, then don't run provisioners
		log.Printf("[TRACE] evalApplyProvisioners: %s is not freshly-created, so no provisioning is required", n.Addr)
		return nil
	}
	if state.Status == states.ObjectTainted {
		// No point in provisioning an object that is already tainted, since
		// it's going to get recreated on the next apply anyway.
		log.Printf("[TRACE] evalApplyProvisioners: %s is tainted, so skipping provisioning", n.Addr)
		return nil
	}

	var allProvs []*configs.Provisioner
	switch {
	case n.Config != nil && n.Config.Managed != nil:
		allProvs = n.Config.Managed.Provisioners
	case n.RemovedConfig != nil && n.RemovedConfig.Managed != nil:
		allProvs = n.RemovedConfig.Managed.Provisioners
	}

	provs := filterProvisioners(allProvs, when)
	if len(provs) == 0 {
		// We have no provisioners, so don't do anything
		return nil
	}

	// Call pre hook
	diags = diags.Append(ctx.Hook(func(h Hook) (HookAction, error) {
		return h.PreProvisionInstance(n.HookResourceIdentity(), state.Value)
	}))
	if diags.HasErrors() {
		return diags
	}

	// If there are no errors, then we append it to our output error
	// if we have one, otherwise we just output it.
	diags = diags.Append(n.applyProvisioners(ctx, state, when, provs))
	if diags.HasErrors() {
		log.Printf("[TRACE] evalApplyProvisioners: %s provisioning failed, but we will continue anyway at the caller's request", n.Addr)
		return diags
	}

	// Call post hook
	return diags.Append(ctx.Hook(func(h Hook) (HookAction, error) {
		return h.PostProvisionInstance(n.HookResourceIdentity(), state.Value)
	}))
}

// filterProvisioners filters the provisioners on the resource to only
// the provisioners specified by the "when" option.
func filterProvisioners(configured []*configs.Provisioner, when configs.ProvisionerWhen) []*configs.Provisioner {
	if len(configured) == 0 {
		return nil
	}

	result := make([]*configs.Provisioner, 0, len(configured))
	for _, p := range configured {
		if p.When == when {
			result = append(result, p)
		}
	}

	return result
}

// applyProvisioners executes the provisioners for a resource.
func (n *NodeAbstractResourceInstance) applyProvisioners(ctx EvalContext, state *states.ResourceInstanceObject, when configs.ProvisionerWhen, provs []*configs.Provisioner) tfdiags.Diagnostics {
	var diags tfdiags.Diagnostics

	// this self is only used for destroy provisioner evaluation, and must
	// refer to the last known value of the resource.
	self := state.Value

	var evalScope func(EvalContext, hcl.Body, cty.Value, *configschema.Block) (cty.Value, tfdiags.Diagnostics)
	switch when {
	case configs.ProvisionerWhenDestroy:
		evalScope = n.evalDestroyProvisionerConfig
	default:
		evalScope = n.evalProvisionerConfig
	}

	// If there's a connection block defined directly inside the resource block
	// then it'll serve as a base connection configuration for all of the
	// provisioners.
	var baseConn hcl.Body
	switch {
	case n.Config != nil && n.Config.Managed != nil && n.Config.Managed.Connection != nil:
		baseConn = n.Config.Managed.Connection.Config
	case n.RemovedConfig != nil && n.RemovedConfig.Managed != nil && n.RemovedConfig.Managed.Connection != nil:
		baseConn = n.RemovedConfig.Managed.Connection.Config
	}

	for _, prov := range provs {
		log.Printf("[TRACE] applyProvisioners: provisioning %s with %q", n.Addr, prov.Type)

		// Get the provisioner
		provisioner, err := ctx.Provisioner(prov.Type)
		if err != nil {
			return diags.Append(err)
		}

		schema, err := ctx.ProvisionerSchema(prov.Type)
		if err != nil {
			// This error probably won't be a great diagnostic, but in practice
			// we typically catch this problem long before we get here, so
			// it should be rare to return via this codepath.
			diags = diags.Append(err)
			return diags
		}

		config, configDiags := evalScope(ctx, prov.Config, self, schema)
		diags = diags.Append(configDiags)
		if diags.HasErrors() {
			return diags
		}

